actly as <?=Helpers::e($x['username'])?> sees it (logged)"><input type="hidden" name="csrf" value="<?=Helpers::csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn small">👁 Login as</button></form><?php endif;?><?php if(($me['role'] ?? '') === 'admin' && (int)$x['id'] !== (int)$me['id']):?><form method="post" action="/accounts/role" style="display:flex;gap:4px" onsubmit="return confirm('Change <?=Helpers::e($x['username'])?> to the selected role? Live sessions end; demotions apply immediately.')"><input type="hidden" name="csrf" value="<?=Helpers::csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><select name="role" title="Role for <?=Helpers::e($x['username'])?>"><?php foreach(['user','reseller','admin'] as $rr):?><option value="<?=$rr?>"<?=($x['role'] ?? '') === $rr ? ' selected' : ''?>><?=$rr?></option><?php endforeach;?></select><button class="btn small">Set</button></form><?php endif;?></div></td></tr><?php endforeach;?>
